#!/usr/bin/env bash
# Exercise replacement in a subprocess so returning to the old menu is detected.
source "$(dirname "$0")/../sb.sh"
ROOT=$(mktemp -d) || exit 1
trap 'rm -rf "$ROOT"' EXIT
fail() { echo "FAIL: $*" >&2; exit 1; }
cat > "$ROOT/download" <<'SCRIPT'
#!/usr/bin/env bash
# Generated by scripts/build.sh; edit sb.sh and lib/*.sh instead.
SB_VERSION="9.9.9"
usage() { :; }
main() {
  if { : >&9; } 2>/dev/null; then exit 42; fi
  echo new-script
}
if [[ ${BASH_SOURCE[0]} == "$0" ]]; then
  main "$@"
  exit $?
fi
SCRIPT
run_case() (
  local scenario=$1 result=0
  SCRIPT_URL=https://example.invalid/sb.sh
  SB_CMD="$ROOT/$scenario"
  curl() { cp "$ROOT/download" "$4"; }
  save_conf() { :; }
  confirm() { [[ $scenario != cancel ]]; }
  if [[ $scenario == install-failure ]]; then install() { return 1; }; fi
  if [[ $scenario == move-failure ]]; then mv() { return 1; }; fi
  exec 9>"$ROOT/lock"
  if [[ $scenario == cli ]]; then
    update_script || result=$?
  else
    update_script restart || result=$?
  fi
  echo "old-script:$result"
)
for scenario in restart cli cancel install-failure move-failure eof; do
  if [[ $scenario == eof ]]; then
    run_case "$scenario" < /dev/null > "$ROOT/output" 2>&1
  else
    run_case "$scenario" <<< '' > "$ROOT/output" 2>&1
  fi
  [[ $? == 0 ]] || fail "$scenario failed"
  case $scenario in
    restart)
      grep -q '^new-script$' "$ROOT/output" || fail 'new script did not run or lock was inherited'
      if grep -q old-script "$ROOT/output"; then fail 'returned to old script'; fi ;;
    eof)
      if grep -Eq 'old-script|new-script' "$ROOT/output"; then fail 'EOF did not exit'; fi ;;
    cli|cancel) grep -q '^old-script:0$' "$ROOT/output" || fail "$scenario did not return" ;;
    *) grep -q '^old-script:1$' "$ROOT/output" || fail 'installation failure ignored' ;;
  esac
done
# A script replaced outside the current process must be loaded before showing a menu.
(
  SB_CMD="$ROOT/download"
  exec 9>"$ROOT/lock"
  main_menu
  echo old-menu-returned
) <<< '' > "$ROOT/output" 2>&1 || fail 'menu reload failed'
grep -q '磁盘已安装 v9.9.9' "$ROOT/output" || fail 'missing version mismatch notice'
grep -q '^new-script$' "$ROOT/output" || fail 'menu did not load installed script'
if grep -Eq 'old-menu-returned|管理脚本 v' "$ROOT/output"; then fail 'stale menu displayed'; fi
# A matching version or a missing installed file must still allow normal menu exit.
for scenario in matching missing; do
  (
    SB_CMD="$ROOT/$scenario"
    [[ $scenario != matching ]] || printf 'SB_VERSION="%s"\n' "$SB_VERSION" > "$SB_CMD"
    svc() { return 0; }
    core_version() { echo test; }
    list_ids() { echo 1; }
    ask() { echo 0; }
    main_menu
  ) > "$ROOT/output" 2>&1 || fail "$scenario menu failed"
  grep -q "管理脚本 v$SB_VERSION" "$ROOT/output" || fail "$scenario menu missing"
done
echo 'PASS: script update regression tests'

# A raw source entry lacks its modules and must never replace an installed command.
(
  SB_CMD="$ROOT/protected"
  printf 'existing-command\n' > "$SB_CMD"
  SCRIPT_URL=https://example.invalid/source
  curl() { printf '#!/usr/bin/env bash\nSB_SOURCE_DIR=/missing\n' > "$4"; }
  confirm() { fail 'source loader reached confirmation'; }
  if update_script; then fail 'source loader installed'; fi
  [[ $(cat "$SB_CMD") == existing-command ]] || fail 'existing command replaced'
) || exit 1

# Empty responses, truncated bundles and invalid versions never reach approval.
for scenario in empty version-only truncated no-version duplicate-version syntax; do
  (
    SB_CMD="$ROOT/protected"
    printf 'existing-command\n' > "$SB_CMD"
    SCRIPT_URL=https://example.invalid/sb.sh
    case $scenario in
      empty) : > "$ROOT/bad-download" ;;
      version-only) printf 'SB_VERSION="1.2.3"\n' > "$ROOT/bad-download" ;;
      truncated) sed '/^if \[\[ /,$d' "$ROOT/download" > "$ROOT/bad-download" ;;
      no-version) sed '/^SB_VERSION=/d' "$ROOT/download" > "$ROOT/bad-download" ;;
      duplicate-version) { echo 'SB_VERSION="1.2.3"'; cat "$ROOT/download"; } > "$ROOT/bad-download" ;;
      syntax) printf 'if then\n' > "$ROOT/bad-download" ;;
    esac
    curl() { cp "$ROOT/bad-download" "$4"; }
    confirm() { fail "$scenario reached confirmation"; }
    if update_script; then fail "$scenario accepted"; fi
    [[ $(cat "$SB_CMD") == existing-command ]] || fail "$scenario replaced installed script"
  ) || exit 1
done

for scenario in valid mismatch missing duplicate; do
  (
    SB_CMD="$ROOT/verified"
    printf 'existing-command\n' > "$SB_CMD"
    SCRIPT_URL=https://github.com/example/sb/releases/latest/download/sb.sh
    sum=$(openssl dgst -sha256 "$ROOT/download"); sum=${sum##* }
    curl() {
      if [[ $2 == */SHA256SUMS ]]; then
        case $scenario in
          missing) return 22 ;;
          mismatch) printf '%064d  sb.sh\n' 0 > "$4" ;;
          duplicate) printf '%s  sb.sh\n%s  sb.sh\n' "$sum" "$sum" > "$4" ;;
          *) printf '%s  sb.sh\n' "$sum" > "$4" ;;
        esac
      else cp "$ROOT/download" "$4"; fi
    }
    confirm() { [[ $scenario == valid ]] || fail 'bad checksum reached confirmation'; }
    save_conf() { :; }
    if [[ $scenario == valid ]]; then
      update_script || fail 'valid release rejected'
      cmp "$ROOT/download" "$SB_CMD" || fail 'release not installed'
    else
      if update_script; then fail 'bad checksum accepted'; fi
      [[ $(cat "$SB_CMD") == existing-command ]] || fail 'bad checksum replaced script'
    fi
  ) || exit 1
done
echo 'PASS: script artifact validation and release checksums'
